def generateBanner(title=None, context_hint=None, max_length=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # No request-log/usage collection in schema; cannot record calls.

    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string")
    if context_hint is not None and not isinstance(context_hint, str):
        return _err("VALIDATION_ERROR", "context_hint must be a string")
    if max_length is not None:
        if not isinstance(max_length, int):
            return _err("VALIDATION_ERROR", "max_length must be an integer")
        if max_length <= 0:
            return _err("VALIDATION_ERROR", "max_length must be positive")

    ml = max_length if max_length is not None else 72

    def _clean(s):
        s = re.sub(r"\s+", " ", (s or "").strip())
        return s

    t = _clean(title) if title is not None else ""
    h = _clean(context_hint) if context_hint is not None else ""

    if t and h:
        base = f"{t} — {h}"
    elif t:
        base = t
    elif h:
        base = h
    else:
        base = "Conversation"

    base = _clean(base)
    if len(base) <= ml:
        banner = base
    else:
        # Prefer cutting at word boundary if possible.
        cut = base[:ml].rstrip()
        if " " in cut:
            cut2 = cut.rsplit(" ", 1)[0].rstrip()
            banner = cut2 if cut2 else cut
        else:
            banner = cut

    if not banner:
        banner = "Conversation"[:ml] if ml > 0 else ""

    return {"banner_text": banner, "max_length": ml}

def checkHealth(include_stats=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if include_stats is not None and not isinstance(include_stats, bool):
        return _err("VALIDATION_ERROR", "include_stats must be a boolean")

    required_files = [
        "conversations.json",
        "messages.json",
        "active_files.json",
        "knowledge_items.json",
        "episodes.json",
    ]

    # Check readable/writable as per business rule.
    if not os.path.isdir(_DB):
        return _err("UNAVAILABLE", "database directory is not available", path=_DB)

    unreadable = []
    unwritable = []
    parsed_ok = True
    stats = {}

    for fn in required_files:
        p = os.path.join(_DB, fn)

        # Readability + JSON parse readiness
        try:
            with open(p, encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, list):
                parsed_ok = False
        except FileNotFoundError:
            # Treat missing as empty but must be writable and creatable
            data = []
        except Exception:
            unreadable.append(fn)
            continue

        # Writability: try open for append/create and close without modifying content
        try:
            os.makedirs(_DB, exist_ok=True)
            # If file exists, open r+; else w then rewrite empty list to satisfy JSON
            if os.path.exists(p):
                with open(p, "r+", encoding="utf-8") as f:
                    pass
            else:
                with open(p, "w", encoding="utf-8") as f:
                    json.dump([], f)
        except Exception:
            unwritable.append(fn)

        if include_stats:
            stats[fn.replace(".json", "")] = {"rows": len(data) if isinstance(data, list) else None}

    if unreadable or unwritable or not parsed_ok:
        return _err(
            "UNAVAILABLE",
            "dependencies are not ready",
            unreadable=unreadable,
            unwritable=unwritable,
            parsed_ok=parsed_ok,
        )

    resp = {
        "status": "healthy",
        "database": {"path": _DB, "collections_ok": True},
        "checked_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
    }
    if include_stats:
        resp["stats"] = stats
    return resp

def initConversation(external_conversation_key, user_message, title=None, recent_messages_limit=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "initConversation"

    def _utc_now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(status_code, meta=None):
        # Observable dynamics: always write a request log if the collection exists or can be created.
        now = _utc_now_iso_z()
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "c10x_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        rate_limits = _load("rate_limits.json")
        if not isinstance(rate_limits, list):
            return None
        rl = next((r for r in rate_limits if r.get("enabled") is True and r.get("endpoint") in (endpoint, "*")), None)
        if not rl:
            return None
        try:
            window_s = int(rl.get("window_seconds"))
            max_req = int(rl.get("max_requests"))
        except Exception:
            return None
        if window_s <= 0 or max_req < 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff_dt = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for row in reversed(logs):
            if row.get("endpoint") not in (endpoint, "*"):
                continue
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            # lexicographic works for ISO-Z, but existing logs might differ; parse best-effort
            try:
                s = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff_dt:
                recent += 1
            else:
                break
        if recent >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window_s, max_requests=max_req)
        return None

    # ---- validate inputs first ----
    if not isinstance(external_conversation_key, str) or not external_conversation_key.strip():
        _log_request("VALIDATION_ERROR", {"field": "external_conversation_key"})
        return _err("VALIDATION_ERROR", "external_conversation_key must be a non-empty string")

    if title is not None and not isinstance(title, str):
        _log_request("VALIDATION_ERROR", {"field": "title"})
        return _err("VALIDATION_ERROR", "title must be a string")

    if recent_messages_limit is None:
        recent_messages_limit = 20
    if not isinstance(recent_messages_limit, int):
        _log_request("VALIDATION_ERROR", {"field": "recent_messages_limit"})
        return _err("VALIDATION_ERROR", "recent_messages_limit must be an integer")
    if recent_messages_limit < 0:
        _log_request("VALIDATION_ERROR", {"field": "recent_messages_limit"})
        return _err("VALIDATION_ERROR", "recent_messages_limit must be >= 0")

    if not isinstance(user_message, dict):
        _log_request("VALIDATION_ERROR", {"field": "user_message"})
        return _err("VALIDATION_ERROR", "user_message must be an object")
    if "content" not in user_message:
        _log_request("VALIDATION_ERROR", {"field": "user_message.content"})
        return _err("VALIDATION_ERROR", "user_message.content is required")
    if not isinstance(user_message.get("content"), str) or user_message.get("content") == "":
        _log_request("VALIDATION_ERROR", {"field": "user_message.content"})
        return _err("VALIDATION_ERROR", "user_message.content must be a non-empty string")
    content_format = user_message.get("content_format", "plain_text")
    if content_format not in ("plain_text", "markdown", "json"):
        _log_request("VALIDATION_ERROR", {"field": "user_message.content_format"})
        return _err("VALIDATION_ERROR", "user_message.content_format must be one of plain_text, markdown, json")
    token_count = user_message.get("token_count", None)
    if token_count is not None:
        if not isinstance(token_count, int):
            _log_request("VALIDATION_ERROR", {"field": "user_message.token_count"})
            return _err("VALIDATION_ERROR", "user_message.token_count must be an integer")
        if token_count < 0:
            _log_request("VALIDATION_ERROR", {"field": "user_message.token_count"})
            return _err("VALIDATION_ERROR", "user_message.token_count must be >= 0")

    # rate limit
    rl_err = _enforce_rate_limit()
    if rl_err:
        _log_request("RATE_LIMIT")
        return rl_err

    # ---- load collections ----
    conversations = _load("conversations.json")
    messages = _load("messages.json")
    active_files = _load("active_files.json")
    knowledge_items = _load("knowledge_items.json")
    episodes = _load("episodes.json")

    if not isinstance(conversations, list): conversations = []
    if not isinstance(messages, list): messages = []
    if not isinstance(active_files, list): active_files = []
    if not isinstance(knowledge_items, list): knowledge_items = []
    if not isinstance(episodes, list): episodes = []

    # ---- find or create conversation (unique external key) ----
    now = _utc_now_iso_z()
    convo = next((c for c in conversations if c.get("external_conversation_key") == external_conversation_key), None)

    if convo is None:
        convo_id = "c10x_convo_" + uuid.uuid4().hex
        banner = (title.strip() if isinstance(title, str) and title.strip() else None)
        if banner:
            banner_text = f"Session: {banner}"
        else:
            banner_text = f"Session: {external_conversation_key[:64]}"
        convo = {
            "id": convo_id,
            "external_conversation_key": external_conversation_key,
            "title": title if isinstance(title, str) and title.strip() else None,
            "banner_text": banner_text,
            "status": "active",
            "started_at": now,
            "ended_at": None,
            "last_activity_at": now,
            "created_at": now,
            "updated_at": now
        }
        # enforce uniqueness: reject if duplicates exist already (shouldn't, but be safe)
        if any(c.get("external_conversation_key") == external_conversation_key for c in conversations):
            _log_request("CONFLICT", {"external_conversation_key": external_conversation_key})
            return _err("CONFLICT", "external_conversation_key already exists")
        conversations.append(convo)
        _save("conversations.json", conversations)
    else:
        # If already exists, allow updating title/banner and re-activating only if still active; no illegal transitions.
        if title is not None and title.strip():
            convo["title"] = title
        if convo.get("banner_text") is None:
            convo["banner_text"] = f"Session: {(convo.get('title') or external_conversation_key)[:64]}"
        # Do not allow re-opening ended conversation via initConversation
        if convo.get("status") == "ended":
            # still return context; no mutation besides request log
            # but we *do* store initial user message per tool description? that would violate business rule for ended convos.
            # So: return INVALID_TRANSITION for write attempt; however initConversation is expected to create or find
            # a session; if ended exists for that key, treat as conflict and create new? uniqueness prevents.
            _log_request("INVALID_TRANSITION", {"conversation_id": convo.get("id")})
            return _err("INVALID_TRANSITION", "Conversation is ended and cannot accept new initialization under the same external_conversation_key.", conversation_id=convo.get("id"))
        convo["last_activity_at"] = now
        convo["updated_at"] = now
        _save("conversations.json", conversations)

    # ---- store initial user message ----
    # enforce "no writes to ended" (already ensured active above)
    convo_id = convo["id"]
    # next sequence (best-effort atomicity within single-process file store)
    max_seq = 0
    for m in messages:
        if m.get("conversation_id") == convo_id:
            s = m.get("sequence")
            if isinstance(s, int) and s > max_seq:
                max_seq = s
    seq = max_seq + 1
    # enforce unique(conversation_id, sequence)
    if any(m.get("conversation_id") == convo_id and m.get("sequence") == seq for m in messages):
        _log_request("CONFLICT", {"conversation_id": convo_id})
        return _err("CONFLICT", "Sequence conflict while storing message.", conversation_id=convo_id, sequence=seq)

    msg_now = _utc_now_iso_z()
    msg = {
        "id": "c10x_msg_" + uuid.uuid4().hex,
        "conversation_id": convo_id,
        "role": "user",
        "content": user_message.get("content"),
        "content_format": content_format,
        "sequence": seq,
        "token_count": token_count,
        "status": "stored",
        "redacted_at": None,
        "created_at": msg_now,
        "updated_at": msg_now
    }
    messages.append(msg)
    _save("messages.json", messages)

    # update last_activity_at again to reflect message write
    for c in conversations:
        if c.get("id") == convo_id:
            c["last_activity_at"] = msg_now
            c["updated_at"] = msg_now
            break
    _save("conversations.json", conversations)

    # ---- assemble context ----
    # recent messages (exclude redacted by default)
    convo_msgs = [m for m in messages if m.get("conversation_id") == convo_id and m.get("status") != "redacted"]
    convo_msgs.sort(key=lambda r: (r.get("sequence") if isinstance(r.get("sequence"), int) else 0, r.get("created_at") or ""), reverse=True)
    if recent_messages_limit == 0:
        recent_msgs = []
    else:
        recent_msgs = convo_msgs[:recent_messages_limit]

    # active files
    convo_files = [f for f in active_files if f.get("conversation_id") == convo_id and f.get("status") == "active"]
    convo_files.sort(key=lambda r: (r.get("last_accessed_at") or ""), reverse=True)

    # knowledge items: include conversation-scoped + global (conversation_id null)
    kn = []
    for it in knowledge_items:
        if it.get("status") != "active":
            continue
        cid = it.get("conversation_id")
        if cid is None or cid == convo_id:
            kn.append(it)
    kn.sort(key=lambda r: (r.get("updated_at") or r.get("created_at") or ""), reverse=True)

    # recent episodes (exclude voided by default)
    eps = [e for e in episodes if e.get("conversation_id") == convo_id and e.get("status") != "voided"]
    eps.sort(key=lambda r: (r.get("sequence") if isinstance(r.get("sequence"), int) else 0, r.get("occurred_at") or ""), reverse=True)

    resp = {
        "conversation": convo,
        "stored_user_message": msg,
        "context": {
            "recent_messages": recent_msgs,
            "active_files": convo_files,
            "active_knowledge_items": kn,
            "recent_episodes": eps
        }
    }
    _log_request("OK", {"conversation_id": convo_id, "created": convo.get("created_at") == convo.get("updated_at")})
    return resp

def endConversation(conversation_id, assistant_message, milestone, episode, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "endConversation"

    def _utc_now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    def _log_request(status_code, meta=None):
        now = _utc_now_iso_z()
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "c10x_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        rate_limits = _load("rate_limits.json")
        if not isinstance(rate_limits, list):
            return None
        rl = next((r for r in rate_limits if r.get("enabled") is True and r.get("endpoint") in (endpoint, "*")), None)
        if not rl:
            return None
        try:
            window_s = int(rl.get("window_seconds"))
            max_req = int(rl.get("max_requests"))
        except Exception:
            return None
        if window_s <= 0 or max_req < 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff_dt = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for row in reversed(logs):
            if row.get("endpoint") not in (endpoint, "*"):
                continue
            ts = row.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                s = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is not None:
                    dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff_dt:
                recent += 1
            else:
                break
        if recent >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window_s, max_requests=max_req)
        return None

    # ---- validate inputs ----
    if not isinstance(conversation_id, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversation_id):
        _log_request("VALIDATION_ERROR", {"field": "conversation_id"})
        return _err("VALIDATION_ERROR", "conversation_id does not match expected format")

    if not isinstance(assistant_message, dict):
        _log_request("VALIDATION_ERROR", {"field": "assistant_message"})
        return _err("VALIDATION_ERROR", "assistant_message must be an object")
    if "content" not in assistant_message:
        _log_request("VALIDATION_ERROR", {"field": "assistant_message.content"})
        return _err("VALIDATION_ERROR", "assistant_message.content is required")
    if not isinstance(assistant_message.get("content"), str) or assistant_message.get("content") == "":
        _log_request("VALIDATION_ERROR", {"field": "assistant_message.content"})
        return _err("VALIDATION_ERROR", "assistant_message.content must be a non-empty string")
    am_format = assistant_message.get("content_format", "plain_text")
    if am_format not in ("plain_text", "markdown", "json"):
        _log_request("VALIDATION_ERROR", {"field": "assistant_message.content_format"})
        return _err("VALIDATION_ERROR", "assistant_message.content_format must be one of plain_text, markdown, json")
    am_tokens = assistant_message.get("token_count", None)
    if am_tokens is not None:
        if not isinstance(am_tokens, int):
            _log_request("VALIDATION_ERROR", {"field": "assistant_message.token_count"})
            return _err("VALIDATION_ERROR", "assistant_message.token_count must be an integer")
        if am_tokens < 0:
            _log_request("VALIDATION_ERROR", {"field": "assistant_message.token_count"})
            return _err("VALIDATION_ERROR", "assistant_message.token_count must be >= 0")

    if not isinstance(milestone, dict):
        _log_request("VALIDATION_ERROR", {"field": "milestone"})
        return _err("VALIDATION_ERROR", "milestone must be an object")
    if "title" not in milestone or "body" not in milestone:
        _log_request("VALIDATION_ERROR", {"field": "milestone"})
        return _err("VALIDATION_ERROR", "milestone.title and milestone.body are required")
    if not isinstance(milestone.get("title"), str) or milestone.get("title") == "":
        _log_request("VALIDATION_ERROR", {"field": "milestone.title"})
        return _err("VALIDATION_ERROR", "milestone.title must be a non-empty string")
    if not isinstance(milestone.get("body"), str) or milestone.get("body") == "":
        _log_request("VALIDATION_ERROR", {"field": "milestone.body"})
        return _err("VALIDATION_ERROR", "milestone.body must be a non-empty string")
    tags = milestone.get("tags", [])
    if tags is None:
        tags = []
    if not isinstance(tags, list) or any(not isinstance(t, str) for t in tags):
        _log_request("VALIDATION_ERROR", {"field": "milestone.tags"})
        return _err("VALIDATION_ERROR", "milestone.tags must be an array of strings")
    effective_at = milestone.get("effective_at", None)
    if effective_at is not None:
        eff = _parse_rfc3339(effective_at)
        if eff is None:
            _log_request("VALIDATION_ERROR", {"field": "milestone.effective_at"})
            return _err("VALIDATION_ERROR", "milestone.effective_at must be an RFC3339 datetime string")
        effective_at = eff

    if not isinstance(episode, dict):
        _log_request("VALIDATION_ERROR", {"field": "episode"})
        return _err("VALIDATION_ERROR", "episode must be an object")
    if "kind" not in episode or "summary" not in episode:
        _log_request("VALIDATION_ERROR", {"field": "episode"})
        return _err("VALIDATION_ERROR", "episode.kind and episode.summary are required")
    if not isinstance(episode.get("kind"), str) or episode.get("kind") == "":
        _log_request("VALIDATION_ERROR", {"field": "episode.kind"})
        return _err("VALIDATION_ERROR", "episode.kind must be a non-empty string")
    if not isinstance(episode.get("summary"), str) or episode.get("summary") == "":
        _log_request("VALIDATION_ERROR", {"field": "episode.summary"})
        return _err("VALIDATION_ERROR", "episode.summary must be a non-empty string")
    ep_payload = episode.get("payload", {})
    if ep_payload is None:
        ep_payload = {}
    if not isinstance(ep_payload, dict):
        _log_request("VALIDATION_ERROR", {"field": "episode.payload"})
        return _err("VALIDATION_ERROR", "episode.payload must be an object")
    occurred_at = episode.get("occurred_at", None)
    if occurred_at is not None:
        occ = _parse_rfc3339(occurred_at)
        if occ is None:
            _log_request("VALIDATION_ERROR", {"field": "episode.occurred_at"})
            return _err("VALIDATION_ERROR", "episode.occurred_at must be an RFC3339 datetime string")
        occurred_at = occ

    rl_err = _enforce_rate_limit()
    if rl_err:
        _log_request("RATE_LIMIT", {"conversation_id": conversation_id})
        return rl_err

    # ---- load state ----
    conversations = _load("conversations.json")
    messages = _load("messages.json")
    knowledge_items = _load("knowledge_items.json")
    episodes = _load("episodes.json")
    if not isinstance(conversations, list): conversations = []
    if not isinstance(messages, list): messages = []
    if not isinstance(knowledge_items, list): knowledge_items = []
    if not isinstance(episodes, list): episodes = []

    convo = next((c for c in conversations if c.get("id") == conversation_id), None)
    if convo is None:
        _log_request("NOT_FOUND", {"conversation_id": conversation_id})
        return _err("NOT_FOUND", "Conversation not found.", conversation_id=conversation_id)

    # idempotency: if already ended, return existing end artifacts (no success without effect: we won't claim new writes)
    if convo.get("status") == "ended":
        # still return last messages/episode context but no new rows
        convo_msgs = [m for m in messages if m.get("conversation_id") == conversation_id and m.get("status") != "redacted"]
        convo_msgs.sort(key=lambda r: (r.get("sequence") if isinstance(r.get("sequence"), int) else 0, r.get("created_at") or ""), reverse=True)
        convo_eps = [e for e in episodes if e.get("conversation_id") == conversation_id and e.get("status") != "voided"]
        convo_eps.sort(key=lambda r: (r.get("sequence") if isinstance(r.get("sequence"), int) else 0, r.get("occurred_at") or ""), reverse=True)
        _log_request("OK", {"conversation_id": conversation_id, "idempotent": True})
        return {
            "conversation": convo,
            "assistant_message": convo_msgs[0] if convo_msgs else None,
            "milestone_item": None,
            "episode": convo_eps[0] if convo_eps else None,
            "idempotent": True
        }

    if convo.get("status") != "active":
        _log_request("INVALID_TRANSITION", {"conversation_id": conversation_id, "from": convo.get("status")})
        return _err("INVALID_TRANSITION", "Conversation is not in a state that can be ended.", conversation_id=conversation_id, status=convo.get("status"))

    now = _utc_now_iso_z()

    # ---- (1) store assistant message ----
    max_seq = 0
    for m in messages:
        if m.get("conversation_id") == conversation_id:
            s = m.get("sequence")
            if isinstance(s, int) and s > max_seq:
                max_seq = s
    msg_seq = max_seq + 1
    if any(m.get("conversation_id") == conversation_id and m.get("sequence") == msg_seq for m in messages):
        _log_request("CONFLICT", {"conversation_id": conversation_id})
        return _err("CONFLICT", "Sequence conflict while storing assistant message.", conversation_id=conversation_id, sequence=msg_seq)

    msg_now = _utc_now_iso_z()
    msg = {
        "id": "c10x_msg_" + uuid.uuid4().hex,
        "conversation_id": conversation_id,
        "role": "assistant",
        "content": assistant_message.get("content"),
        "content_format": am_format,
        "sequence": msg_seq,
        "token_count": am_tokens,
        "status": "stored",
        "redacted_at": None,
        "created_at": msg_now,
        "updated_at": msg_now
    }
    messages.append(msg)
    _save("messages.json", messages)

    # ---- (2) create milestone knowledge item ----
    kn_now = _utc_now_iso_z()
    kn = {
        "id": "c10x_kn_" + uuid.uuid4().hex,
        "conversation_id": conversation_id,
        "type": "milestone",
        "title": milestone.get("title"),
        "body": milestone.get("body"),
        "tags": tags,
        "status": "active",
        "effective_at": effective_at,
        "supersedes_id": None,
        "created_at": kn_now,
        "updated_at": kn_now
    }
    knowledge_items.append(kn)
    _save("knowledge_items.json", knowledge_items)

    # ---- (3) record a conversation_end episode (override kind per business rule) ----
    ep_max_seq = 0
    for e in episodes:
        if e.get("conversation_id") == conversation_id:
            s = e.get("sequence")
            if isinstance(s, int) and s > ep_max_seq:
                ep_max_seq = s
    ep_seq = ep_max_seq + 1
    if any(e.get("conversation_id") == conversation_id and e.get("sequence") == ep_seq for e in episodes):
        _log_request("CONFLICT", {"conversation_id": conversation_id})
        return _err("CONFLICT", "Sequence conflict while recording episode.", conversation_id=conversation_id, sequence=ep_seq)

    occurred = occurred_at or _utc_now_iso_z()
    # payload must reference created ids
    payload = dict(ep_payload)
    payload.setdefault("assistant_message_id", msg["id"])
    payload.setdefault("milestone_id", kn["id"])
    payload.setdefault("tool", endpoint)

    ep_row = {
        "id": "c10x_ep_" + uuid.uuid4().hex,
        "conversation_id": conversation_id,
        "kind": "conversation_end",
        "summary": episode.get("summary"),
        "payload": payload,
        "sequence": ep_seq,
        "status": "recorded",
        "occurred_at": occurred,
        "created_at": now,
        "updated_at": now
    }
    episodes.append(ep_row)
    _save("episodes.json", episodes)

    # finally end conversation (legal transition active -> ended)
    convo["status"] = "ended"
    convo["ended_at"] = now
    convo["last_activity_at"] = now
    convo["updated_at"] = now
    _save("conversations.json", conversations)

    _log_request("OK", {"conversation_id": conversation_id, "assistant_message_id": msg["id"], "milestone_id": kn["id"], "episode_id": ep_row["id"]})
    return {
        "conversation": convo,
        "assistant_message": msg,
        "milestone_item": kn,
        "episode": ep_row
    }

def storeUserMessage(conversation_id, content, content_format=None, token_count=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "storeUserMessage"

    def _utc_now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if isinstance(ts, str) and ts.endswith("Z"):
            try:
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            except Exception:
                return None
        return None

    def _log_request(status_code, meta=None):
        now = _utc_now_iso_z()
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "c10x_req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": None,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": now,
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        rate_limits = _load("rate_limits.json")
        if not isinstance(rate_limits, list):
            return None
        rl = next((r for r in rate_limits if r.get("enabled") is True and r.get("endpoint") == endpoint), None)
        if rl is None:
            rl = next((r for r in rate_limits if r.get("enabled") is True and r.get("endpoint") == "*"), None)
        if not rl:
            return None
        try:
            window_s = int(rl.get("window_seconds"))
            max_req = int(rl.get("max_requests"))
        except Exception:
            return None
        if window_s <= 0 or max_req < 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = time.time() - window_s
        cnt = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt.timestamp() >= cutoff:
                cnt += 1
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded.", endpoint=endpoint, window_seconds=window_s, max_requests=max_req)
        return None

    # Enforce rate limit before doing work (but log even failures)
    rl_err = _enforce_rate_limit()
    if rl_err:
        _log_request("RATE_LIMIT", {"conversation_id": conversation_id})
        return rl_err

    # Validate inputs
    if not isinstance(conversation_id, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversation_id):
        _log_request("VALIDATION_ERROR", {"field": "conversation_id"})
        return _err("VALIDATION_ERROR", "Invalid conversation_id format.", field="conversation_id")

    if not isinstance(content, str) or content == "":
        _log_request("VALIDATION_ERROR", {"field": "content"})
        return _err("VALIDATION_ERROR", "Missing/empty content.", field="content")

    if content_format is None:
        content_format = "plain_text"
    if not isinstance(content_format, str) or content_format not in ("plain_text", "markdown", "json"):
        _log_request("VALIDATION_ERROR", {"field": "content_format"})
        return _err("VALIDATION_ERROR", "Invalid content_format.", field="content_format", allowed=["plain_text", "markdown", "json"])

    if token_count is not None and not isinstance(token_count, int):
        _log_request("VALIDATION_ERROR", {"field": "token_count"})
        return _err("VALIDATION_ERROR", "token_count must be an integer.", field="token_count")
    if isinstance(token_count, int) and token_count < 0:
        _log_request("VALIDATION_ERROR", {"field": "token_count"})
        return _err("VALIDATION_ERROR", "token_count must be >= 0.", field="token_count")

    # Load conversation
    conversations = _load("conversations.json")
    if not isinstance(conversations, list):
        conversations = []
    convo = next((c for c in conversations if c.get("id") == conversation_id), None)
    if convo is None:
        _log_request("NOT_FOUND", {"conversation_id": conversation_id})
        return _err("NOT_FOUND", "Conversation not found.", conversation_id=conversation_id)

    # Business rule: no writes to ended conversations
    if convo.get("status") == "ended":
        _log_request("INVALID_TRANSITION", {"conversation_id": conversation_id, "status": "ended"})
        return _err("INVALID_TRANSITION", "Cannot write to an ended conversation.", conversation_id=conversation_id)

    # Atomic-ish sequence assignment (best effort in JSON store): lock via exclusive create file
    lock_path = os.path.join(_DB, f".lock_msg_{conversation_id}")
    lock_fd = None
    try:
        try:
            lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_RDWR)
        except FileExistsError:
            # If locked, we still must not raise; refuse as rate-limited-like contention
            _log_request("CONFLICT", {"conversation_id": conversation_id, "lock": "messages"})
            return _err("CONFLICT", "Conversation is busy; please retry.", conversation_id=conversation_id)

        messages = _load("messages.json")
        if not isinstance(messages, list):
            messages = []

        # Compute next sequence for this conversation
        max_seq = 0
        for m in messages:
            if m.get("conversation_id") == conversation_id:
                s = m.get("sequence")
                if isinstance(s, int) and s > max_seq:
                    max_seq = s
        next_seq = max_seq + 1
        if next_seq < 1:
            next_seq = 1

        now = _utc_now_iso_z()
        msg_id = "c10x_msg_" + uuid.uuid4().hex

        row = {
            "id": msg_id,
            "conversation_id": conversation_id,
            "role": "user",
            "content": content,
            "content_format": content_format,
            "sequence": next_seq,
            "token_count": token_count,
            "status": "stored",
            "redacted_at": None,
            "created_at": now,
            "updated_at": now,
        }

        # Enforce unique(conversation_id, sequence)
        if any((m.get("conversation_id") == conversation_id and m.get("sequence") == next_seq) for m in messages):
            _log_request("CONFLICT", {"conversation_id": conversation_id, "sequence": next_seq})
            return _err("CONFLICT", "Sequence conflict; please retry.", conversation_id=conversation_id, sequence=next_seq)

        messages.append(row)
        _save("messages.json", messages)

        # Update conversation last_activity_at/updated_at; maintain constraints around ended_at
        convo["last_activity_at"] = now
        convo["updated_at"] = now
        if convo.get("status") == "active":
            convo["ended_at"] = None
        _save("conversations.json", conversations)

        _log_request("OK", {"conversation_id": conversation_id, "message_id": msg_id, "sequence": next_seq})
        return {"message": row}
    except Exception as e:
        _log_request("ERROR", {"conversation_id": conversation_id, "exception": str(e)})
        return _err("CONFLICT", "Failed to store message due to a transient error.", conversation_id=conversation_id)
    finally:
        if lock_fd is not None:
            try:
                os.close(lock_fd)
            except Exception:
                pass
            try:
                os.remove(lock_path)
            except Exception:
                pass

