        _log_request("VALIDATION_ERROR", {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "inactive"])

    if repo_root is not None and not isinstance(repo_root, str):
        _log_request("VALIDATION_ERROR", {"field": "repo_root"})
        return _err("VALIDATION_ERROR", "repo_root must be a string.", field="repo_root")

    if language is not None and not isinstance(language, str):
        _log_request("VALIDATION_ERROR", {"field": "language"})
        return _err("VALIDATION_ERROR", "language must be a string.", field="language")

    conversations = _load("conversations.json")
    if not isinstance(conversations, list):
        conversations = []
    convo = next((c for c in conversations if c.get("id") == conversation_id), None)
    if convo is None:
        _log_request("NOT_FOUND", {"conversation_id": conversation_id})
        return _err("NOT_FOUND", "Conversation not found.", conversation_id=conversation_id)

    if convo.get("status") == "ended":
        _log_request("INVALID_TRANSITION", {"conversation_id": conversation_id, "status": "ended"})
        return _err("INVALID_TRANSITION", "Cannot write to an ended conversation.", conversation_id=conversation_id)

    active_files = _load("active_files.json")
    if not isinstance(active_files, list):
        active_files = []

    # Upsert key: (conversation_id, repo_root, path)
    def _same_key(r):
        return r.get("conversation_id") == conversation_id and r.get("path") == path and r.get("repo_root") == repo_root

    now = _utc_now_iso_z()
    row = next((r for r in active_files if _same_key(r)), None)

    try:
        if row is None:
            file_id = "c10x_file_" + uuid.uuid4().hex
            row = {
                "id": file_id,
                "conversation_id": conversation_id,
                "path": path,
                "repo_root": repo_root,
                "language": language,
                "status": status,
                "first_seen_at": now,
                "last_accessed_at": now,
                "access_count": 1,
                "created_at": now,
                "updated_at": now,
            }
            # Enforce unique(conversation_id, repo_root, path)
            if any(_same_key(r) for r in active_files):
                _log_request("CONFLICT", {"conversation_id": conversation_id, "path": path, "repo_root": repo_root})
                return _err("CONFLICT", "Active file key conflict; please retry.", conversation_id=conversation_id, path=path, repo_root=repo_root)

            active_files.append(row)
            _save("active_files.json", active_files)
        else:
            # Lifecycle transition always allowed between active/inactive per schema
            # Update fields
            row["status"] = status
            if language is not None:
                row["language"] = language
            row["last_accessed_at"] = now
            ac = row.get("access_count")
            if not isinstance(ac, int) or ac < 0:
                ac = 0
            row["access_count"] = ac + 1
            row["updated_at"] = now
            _save("active_files.json", active_files)

        # Update conversation last_activity_at
        convo["last_activity_at"] = now
        convo["updated_at"] = now
        _save("conversations.json", conversations)

        _log_request("OK", {"conversation_id": conversation_id, "file_id": row.get("id"), "path": path, "repo_root": repo_root})
        return {"active_file": row}
    except Exception as e:
        _log_request("ERROR", {"conversation_id": conversation_id, "exception": str(e)})
        return _err("CONFLICT", "Failed to track file due to a transient error.", conversation_id=conversation_id, path=path, repo_root=repo_root)

def getRecentMessages(conversation_id, limit=None, before_sequence=None, order=None, include_redacted=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    endpoint = "getRecentMessages"
    credential_id = None

    def _finalize(status_code, resp):
        latency_ms = int((time.time() - _t0) * 1000)
        logs.append({
            "id": "c10x_req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return resp

    rate_limits = _load("rate_limits.json")
    if isinstance(rate_limits, list):
        rl = next((r for r in rate_limits if r.get("endpoint") in (endpoint, "*") and r.get("enabled") is True), None)
        if rl:
            window_s = rl.get("window_seconds")
            max_req = rl.get("max_requests")
            try:
                window_s = int(window_s)
                max_req = int(max_req)
            except Exception:
                window_s = None
                max_req = None
            if window_s and max_req and window_s > 0 and max_req >= 0:
                cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
                recent = 0
                for row in reversed(logs):
                    if row.get("endpoint") not in (endpoint, "*"):
                        continue
                    ts = row.get("timestamp")
                    if isinstance(ts, str) and ts >= cutoff:
                        recent += 1
                    else:
                        break
                if recent >= max_req:
                    return _finalize("RATE_LIMIT", _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=window_s, max_requests=max_req))

    if not isinstance(conversation_id, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversation_id):
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid conversation_id format.", field="conversation_id"))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "limit must be an integer.", field="limit"))
    if limit < 1 or limit > 500:
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit"))

    if before_sequence is not None and not isinstance(before_sequence, int):
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "before_sequence must be an integer.", field="before_sequence"))
    if before_sequence is not None and before_sequence < 1:
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "before_sequence must be >= 1.", field="before_sequence"))

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid order.", field="order"))

    if include_redacted is None:
        include_redacted = False
    if not isinstance(include_redacted, bool):
        return _finalize("VALIDATION_ERROR", _err("VALIDATION_ERROR", "include_redacted must be a boolean.", field="include_redacted"))

    conversations = _load("conversations.json")
    if not isinstance(conversations, list):
        conversations = []
    convo = next((c for c in conversations if c.get("id") == conversation_id), None)
    if not convo:
        return _finalize("NOT_FOUND", _err("NOT_FOUND", "Conversation not found.", conversation_id=conversation_id))

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    rows = []
    for m in messages:
        if m.get("conversation_id") != conversation_id:
            continue
        if (not include_redacted) and m.get("status") == "redacted":
            continue
        seq = m.get("sequence")
        if before_sequence is not None and isinstance(seq, int):
            if seq >= before_sequence:
                continue
        rows.append(m)

    def _seq(m):
        s = m.get("sequence")
        return s if isinstance(s, int) else -1

    # stable-ish tie-break by created_at desc for equal seq
    rows.sort(key=lambda m: (_seq(m), m.get("created_at") or ""), reverse=(order == "desc"))
    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        # pagination by sequence strictly less than
        next_cursor = page[-1].get("sequence")

    return _finalize("OK", {
        "messages": page,
        "meta": {
            "conversation_id": conversation_id,
            "order": order,
            "limit": limit,
            "before_sequence": before_sequence,
            "include_redacted": include_redacted,
            "total_matched": total,
            "returned": len(page),
            "has_more": has_more,
            "next_before_sequence": next_cursor
        }
    })

def getActiveFiles(conversationId, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
