    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Usage/audit log (optional)
    def _log(status_code, error_code=None, error_message=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "c10x_req_" + secrets.token_hex(12),
                "endpoint": "getActiveFiles",
                "ts": now,
                "status": status_code,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs
    if not isinstance(conversationId, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversationId):
        _log(400, "VALIDATION_ERROR", "Invalid conversationId format")
        return _err("VALIDATION_ERROR", "Invalid conversationId format", field="conversationId")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "inactive"):
            _log(400, "VALIDATION_ERROR", "Invalid status enum")
            return _err("VALIDATION_ERROR", "Invalid status enum", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, "VALIDATION_ERROR", "Invalid limit; must be between 1 and 200")
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200", field="limit")

    if sortBy is None:
        sortBy = "last_accessed_at"
    if not isinstance(sortBy, str) or sortBy not in ("last_accessed_at", "first_seen_at", "access_count", "created_at", "updated_at"):
        _log(400, "VALIDATION_ERROR", "Invalid sortBy enum")
        return _err("VALIDATION_ERROR", "Invalid sortBy enum", field="sortBy")

    if sortOrder is None:
        sortOrder = "desc"
    if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
        _log(400, "VALIDATION_ERROR", "Invalid sortOrder enum")
        return _err("VALIDATION_ERROR", "Invalid sortOrder enum", field="sortOrder")

    # Auth (ambient) — no explicit credentials in schema; allow if DB present.
    # If datastore unreadable/writable, treat as UNAUTHORIZED (service cannot fulfill).
    if not os.path.isdir(_DB):
        _log(401, "UNAUTHORIZED", "Datastore unavailable")
        return _err("UNAUTHORIZED", "Datastore unavailable")

    conversations = _load("conversations.json")
    if not isinstance(conversations, list):
        _log(401, "UNAUTHORIZED", "Datastore unreadable")
        return _err("UNAUTHORIZED", "Datastore unreadable")
    convo = next((c for c in conversations if isinstance(c, dict) and c.get("id") == conversationId), None)
    if convo is None:
        _log(404, "NOT_FOUND", "Conversation not found")
        return _err("NOT_FOUND", "Conversation not found", resource="conversation", id=conversationId)

    # Cursor handling: opaque base64url-encoded JSON {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log(400, "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        try:
            pad = "=" * ((4 - (len(cursor) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                _log(400, "VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            _log(400, "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    files = _load("active_files.json")
    if not isinstance(files, list):
        _log(401, "UNAUTHORIZED", "Datastore unreadable")
        return _err("UNAUTHORIZED", "Datastore unreadable")

    rows = [r for r in files if isinstance(r, dict) and r.get("conversation_id") == conversationId]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    def _sort_key(r):
        v = r.get(sortBy)
        # Ensure deterministic ordering; tie-breakers
        return (v is None, v, r.get("id"))

    reverse = (sortOrder == "desc")
    # For numbers, None sorts last via tuple; for datetimes as strings, isoformat sorts lexicographically
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {
        "conversationId": conversationId,
        "items": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log(200, meta={"returned": len(page), "total": total})
    return resp

