    if effectiveAt is not None:
        if not isinstance(effectiveAt, str) or effectiveAt.strip() == "":
            _log(400, "VALIDATION_ERROR", "Invalid effectiveAt")
            return _err("VALIDATION_ERROR", "Invalid effectiveAt", field="effectiveAt")
        try:
            s = effectiveAt
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            eff_dt = datetime.datetime.fromisoformat(s)
            if eff_dt.tzinfo is None:
                eff_dt = eff_dt.replace(tzinfo=datetime.timezone.utc)
            eff = eff_dt.astimezone(datetime.timezone.utc).isoformat()
        except ValueError:
