    knowledge = _load("knowledge_items.json")
    if not isinstance(knowledge, list):
        _log(401, "UNAUTHORIZED", "Datastore unreadable")
        return _err("UNAUTHORIZED", "Datastore unreadable")

    if supersedesId is not None:
        if supersedesId == "":
            supersedesId = None
        if supersedesId is not None:
            if not any(isinstance(k, dict) and k.get("id") == supersedesId for k in knowledge):
                _log(404, "NOT_FOUND", "supersedesId not found")
                return _err("NOT_FOUND", "supersedesId not found", resource="knowledge_item", id=supersedesId)

    # Insert
    new_id = "c10x_kn_" + secrets.token_hex(12)
    if supersedesId is not None and supersedesId == new_id:
        _log(400, "VALIDATION_ERROR", "supersedesId must not equal id")
        return _err("VALIDATION_ERROR", "supersedesId must not equal id", field="supersedesId")

    row = {
        "id": new_id,
        "conversation_id": conversationId,
        "type": "milestone",
        "title": title,
        "body": body,
        "tags": tags,
        "status": status,
        "effective_at": eff,
        "supersedes_id": supersedesId,
        "created_at": now,
        "updated_at": now
    }

    knowledge.append(row)

    # Side-effect: update conversation last_activity_at
    convo_updated = False
    for c in conversations:
        if isinstance(c, dict) and c.get("id") == conversationId:
            c["last_activity_at"] = now
            c["updated_at"] = now
            convo_updated = True
            break

    if not convo_updated:
        _log(404, "NOT_FOUND", "Conversation not found")
        return _err("NOT_FOUND", "Conversation not found", resource="conversation", id=conversationId)

    _save("knowledge_items.json", knowledge)
    _save("conversations.json", conversations)

    _log(201, meta={"knowledge_item_id": new_id, "type": "milestone"})
    return {"knowledge_item": row}

