def recordEpisode(conversationId, kind, summary, payload=None, sequence=None, status=None, occurredAt=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "recordEpisode"
    ts = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validate inputs
    if not isinstance(conversationId, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversationId):
        return _err("VALIDATION_ERROR", "conversationId must be a c10x_convo_* id")
    if not isinstance(kind, str) or kind.strip() == "":
        return _err("VALIDATION_ERROR", "kind is required and must be non-empty")
    if not isinstance(summary, str) or summary.strip() == "":
        return _err("VALIDATION_ERROR", "summary is required and must be non-empty")

    if payload is None:
        payload = {}
    if not isinstance(payload, dict):
        return _err("VALIDATION_ERROR", "payload must be an object")

    if sequence is not None:
        if not isinstance(sequence, int):
            return _err("VALIDATION_ERROR", "sequence must be an integer")
        if sequence < 0:
            return _err("VALIDATION_ERROR", "sequence must be >= 0")

    if status is None:
        status = "recorded"
    if status not in ("recorded", "voided"):
        return _err("VALIDATION_ERROR", "status must be one of: recorded, voided")

    occurred_iso = None
    if occurredAt is None:
        occurred_iso = ts
    else:
        if not isinstance(occurredAt, str) or occurredAt.strip() == "":
            return _err("VALIDATION_ERROR", "occurredAt must be a valid date-time string")
        s = occurredAt.strip()
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            occurred_iso = dt.astimezone(datetime.timezone.utc).isoformat()
        except ValueError:
            return _err("VALIDATION_ERROR", "occurredAt must be a valid ISO 8601 date-time")

    # Load DB
    conversations = _load("conversations.json")
    episodes = _load("episodes.json")
    request_log = _load("request_log.json")  # optional; may not exist

    convo = next((c for c in conversations if c.get("id") == conversationId), None)
    if convo is None:
        # log call
        request_log.append({
            "id": f"c10x_req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "conversation_id": conversationId,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": ts
        })
        _save("request_log.json", request_log)
        return _err("NOT_FOUND", "conversation not found")

    # No writes to ended conversations unless postmortem
    if convo.get("status") == "ended" and kind != "postmortem":
        request_log.append({
            "id": f"c10x_req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "conversation_id": conversationId,
            "status": "INVALID_TRANSITION",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": ts
        })
        _save("request_log.json", request_log)
        return _err("INVALID_TRANSITION", "cannot record episode for ended conversation unless kind='postmortem'")

    # Determine next sequence (server-assigned, monotonic per-conversation)
    existing_seqs = [e.get("sequence") for e in episodes if e.get("conversation_id") == conversationId and isinstance(e.get("sequence"), int)]
    next_seq = (max(existing_seqs) + 1) if existing_seqs else 1

    # If caller provided sequence, treat as desired but enforce uniqueness and monotonic >=1
    if sequence is not None:
        if sequence == 0:
            return _err("VALIDATION_ERROR", "sequence must be >= 1 when provided")
        if any(e.get("conversation_id") == conversationId and e.get("sequence") == sequence for e in episodes):
            request_log.append({
                "id": f"c10x_req_{uuid.uuid4().hex}",
                "endpoint": endpoint,
                "conversation_id": conversationId,
                "status": "CONFLICT",
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": ts
            })
            _save("request_log.json", request_log)
            return _err("CONFLICT", "episode sequence already exists for this conversation")
        # ensure monotonic (can't be less than 1; already checked) - allow gaps, but not behind current max
        if existing_seqs and sequence <= max(existing_seqs):
            return _err("CONFLICT", "provided sequence must be greater than existing max sequence")
        assigned_seq = sequence
    else:
        assigned_seq = next_seq

    # Create episode
    now_iso = ts
    ep_id = f"c10x_ep_{uuid.uuid4().hex}"
    episode_row = {
        "id": ep_id,
        "conversation_id": conversationId,
        "kind": kind,
        "summary": summary,
        "payload": payload,
        "sequence": assigned_seq,
        "status": status,
        "occurred_at": occurred_iso,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Validate constraints
    if episode_row["sequence"] < 1:
        return _err("VALIDATION_ERROR", "sequence must be >= 1")
    if not isinstance(episode_row["summary"], str) or episode_row["summary"] == "":
        return _err("VALIDATION_ERROR", "summary must be non-empty")

    episodes.append(episode_row)
    _save("episodes.json", episodes)

    # Update conversation last_activity_at
    convo["last_activity_at"] = now_iso
    convo["updated_at"] = now_iso
    _save("conversations.json", conversations)

    # Log call
    request_log.append({
        "id": f"c10x_req_{uuid.uuid4().hex}",
        "endpoint": endpoint,
        "conversation_id": conversationId,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": ts
    })
    _save("request_log.json", request_log)

    return {"episode": episode_row}

def getRecentEpisodes(conversationId, status=None, kind=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getRecentEpisodes"
    ts = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(conversationId, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversationId):
        return _err("VALIDATION_ERROR", "conversationId must be a c10x_convo_* id")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

    if status is not None and status not in ("recorded", "voided"):
        return _err("VALIDATION_ERROR", "status must be one of: recorded, voided")

    if sortBy is None:
        sortBy = "sequence"
    if sortBy not in ("occurred_at", "sequence", "created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sortBy must be one of: occurred_at, sequence, created_at, updated_at")

    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc")

    # Load DB
    conversations = _load("conversations.json")
    episodes = _load("episodes.json")
    request_log = _load("request_log.json")  # optional

    convo = next((c for c in conversations if c.get("id") == conversationId), None)
    if convo is None:
        request_log.append({
            "id": f"c10x_req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "conversation_id": conversationId,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": ts
        })
        _save("request_log.json", request_log)
        return _err("NOT_FOUND", "conversation not found")

    # Decode cursor (offset-based)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if obj.get("conversationId") != conversationId:
                return _err("VALIDATION_ERROR", "cursor does not match conversationId")
            if not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    rows = [e for e in episodes if e.get("conversation_id") == conversationId]

    # Internal policy: exclude voided unless explicitly requested by status filter
    if status is None:
        rows = [e for e in rows if e.get("status") != "voided"]
    else:
        rows = [e for e in rows if e.get("status") == status]

    if kind is not None:
        if not isinstance(kind, str):
            return _err("VALIDATION_ERROR", "kind must be a string")
        rows = [e for e in rows if e.get("kind") == kind]

    def _key(e):
        v = e.get(sortBy)
        if sortBy == "sequence":
            return v if isinstance(v, int) else -1
        # datetime-like fields: compare as ISO strings (works for consistent isoformat)
        return v if isinstance(v, str) else ""
    reverse = (sortOrder == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload_obj = {"conversationId": conversationId, "offset": next_offset, "sortBy": sortBy, "sortOrder": sortOrder, "status": status, "kind": kind}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload_obj, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    request_log.append({
        "id": f"c10x_req_{uuid.uuid4().hex}",
        "endpoint": endpoint,
        "conversation_id": conversationId,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": ts
    })
    _save("request_log.json", request_log)

    return {
        "episodes": page,
        "page_info": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def getComprehensiveContext(conversationId, messagesLimit=None, episodesLimit=None, activeFilesLimit=None, knowledgeLimit=None, includeMessages=None, includeActiveFiles=None, includeKnowledgeItems=None, includeEpisodes=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
