    endpoint = "getComprehensiveContext"
    ts = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(conversationId, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversationId):
        return _err("VALIDATION_ERROR", "conversationId must be a c10x_convo_* id")

    def _val_limit(name, v, lo, hi, default):
        if v is None:
            return default
        if not isinstance(v, int) or v < lo or v > hi:
            return _err("VALIDATION_ERROR", f"{name} must be between {lo} and {hi}")
        return v

    ml = _val_limit("messagesLimit", messagesLimit, 1, 500, 50)
    if isinstance(ml, dict) and "error" in ml: return ml
    el = _val_limit("episodesLimit", episodesLimit, 1, 500, 50)
    if isinstance(el, dict) and "error" in el: return el
    afl = _val_limit("activeFilesLimit", activeFilesLimit, 1, 200, 50)
    if isinstance(afl, dict) and "error" in afl: return afl
    kl = _val_limit("knowledgeLimit", knowledgeLimit, 1, 500, 100)
    if isinstance(kl, dict) and "error" in kl: return kl

    def _val_bool(name, v, default):
        if v is None:
            return default
        if not isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a boolean")
        return v

    inc_msg = _val_bool("includeMessages", includeMessages, True)
    if isinstance(inc_msg, dict) and "error" in inc_msg: return inc_msg
    inc_af = _val_bool("includeActiveFiles", includeActiveFiles, True)
    if isinstance(inc_af, dict) and "error" in inc_af: return inc_af
    inc_ki = _val_bool("includeKnowledgeItems", includeKnowledgeItems, True)
    if isinstance(inc_ki, dict) and "error" in inc_ki: return inc_ki
    inc_ep = _val_bool("includeEpisodes", includeEpisodes, True)
    if isinstance(inc_ep, dict) and "error" in inc_ep: return inc_ep

    conversations = _load("conversations.json")
    messages = _load("messages.json")
    active_files = _load("active_files.json")
    knowledge_items = _load("knowledge_items.json")
    episodes = _load("episodes.json")
    request_log = _load("request_log.json")

    convo = next((c for c in conversations if c.get("id") == conversationId), None)
    if convo is None:
        request_log.append({
            "id": f"c10x_req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "conversation_id": conversationId,
            "status": "NOT_FOUND",
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": ts
        })
        _save("request_log.json", request_log)
        return _err("NOT_FOUND", "conversation not found")

    ctx = {
        "conversation": convo,
        "messages": [],
        "active_files": [],
        "knowledge_items": [],
        "episodes": []
    }

    # Messages: recent, exclude redacted by default
    if inc_msg:
        rows = [m for m in messages if m.get("conversation_id") == conversationId and m.get("status") != "redacted"]
        rows.sort(key=lambda m: (m.get("sequence") if isinstance(m.get("sequence"), int) else -1, m.get("created_at") or ""), reverse=True)
        ctx["messages"] = rows[:ml]

    # Active files: only active, ordered by last_accessed_at desc
    if inc_af:
        rows = [af for af in active_files if af.get("conversation_id") == conversationId and af.get("status") == "active"]
        rows.sort(key=lambda af: af.get("last_accessed_at") or "", reverse=True)
        ctx["active_files"] = rows[:afl]

    # Episodes: recent, exclude voided by default
    if inc_ep:
        rows = [e for e in episodes if e.get("conversation_id") == conversationId and e.get("status") != "voided"]
        rows.sort(key=lambda e: (e.get("sequence") if isinstance(e.get("sequence"), int) else -1, e.get("occurred_at") or ""), reverse=True)
        ctx["episodes"] = rows[:el]

    # Knowledge: active, include conversation-scoped plus global (conversation_id is null)
    if inc_ki:
        rows = []
        for ki in knowledge_items:
            if ki.get("status") != "active":
                continue
            cid = ki.get("conversation_id", None)
            if cid is None or cid == conversationId:
                rows.append(ki)
        rows.sort(key=lambda ki: ki.get("updated_at") or ki.get("created_at") or "", reverse=True)
        ctx["knowledge_items"] = rows[:kl]

    request_log.append({
        "id": f"c10x_req_{uuid.uuid4().hex}",
        "endpoint": endpoint,
        "conversation_id": conversationId,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": ts
    })
    _save("request_log.json", request_log)

    return {
        "context": ctx,
        "limits": {
            "messagesLimit": ml,
            "episodesLimit": el,
            "activeFilesLimit": afl,
            "knowledgeLimit": kl
        },
        "included": {
            "includeMessages": inc_msg,
            "includeActiveFiles": inc_af,
            "includeKnowledgeItems": inc_ki,
            "includeEpisodes": inc_ep
        }
    }

def getMemoryStats(conversationId=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getMemoryStats"
    ts = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if conversationId is not None:
        if not isinstance(conversationId, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversationId):
            return _err("VALIDATION_ERROR", "conversationId must be a c10x_convo_* id")

    conversations = _load("conversations.json")
    messages = _load("messages.json")
    active_files = _load("active_files.json")
    knowledge_items = _load("knowledge_items.json")
    episodes = _load("episodes.json")
    request_log = _load("request_log.json")

    if conversationId is not None:
        convo = next((c for c in conversations if c.get("id") == conversationId), None)
        if convo is None:
            request_log.append({
                "id": f"c10x_req_{uuid.uuid4().hex}",
                "endpoint": endpoint,
                "conversation_id": conversationId,
                "status": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
                "ts": ts
            })
            _save("request_log.json", request_log)
            return _err("NOT_FOUND", "conversation not found")

    def _scope(rows, field="conversation_id"):
        if conversationId is None:
            return rows
        return [r for r in rows if r.get(field) == conversationId]

    scoped_messages = _scope(messages)
    scoped_active_files = _scope(active_files)
    scoped_episodes = _scope(episodes)
    # Knowledge items: in scoped mode, include conversation_id==conversationId plus global (null) (as supported)
    if conversationId is None:
        scoped_knowledge = knowledge_items
    else:
        scoped_knowledge = [ki for ki in knowledge_items if ki.get("conversation_id") in (None, conversationId)]

    # Messages stats
    msg_total = len(scoped_messages)
    msg_stored = sum(1 for m in scoped_messages if m.get("status") == "stored")
    msg_redacted = sum(1 for m in scoped_messages if m.get("status") == "redacted")
    token_sum = 0
    token_present = 0
    for m in scoped_messages:
        tc = m.get("token_count")
        if isinstance(tc, int):
            if tc < 0:
                return _err("VALIDATION_ERROR", "invalid negative token_count aggregate encountered")
            token_sum += tc
            token_present += 1

    # Active files stats
    af_total = len(scoped_active_files)
    af_active = sum(1 for af in scoped_active_files if af.get("status") == "active")
    af_inactive = sum(1 for af in scoped_active_files if af.get("status") == "inactive")

    # Knowledge stats
    ki_total = len(scoped_knowledge)
    ki_by_type = {"milestone": 0, "decision": 0, "requirement": 0}
    ki_by_status = {"active": 0, "superseded": 0, "archived": 0}
    for ki in scoped_knowledge:
        t = ki.get("type")
        s = ki.get("status")
        if t in ki_by_type:
            ki_by_type[t] += 1
        if s in ki_by_status:
            ki_by_status[s] += 1

    # Episodes stats
    ep_total = len(scoped_episodes)
    ep_recorded = sum(1 for e in scoped_episodes if e.get("status") == "recorded")
    ep_voided = sum(1 for e in scoped_episodes if e.get("status") == "voided")

    # Freshness (max timestamps)
    def _max_ts(rows, field):
        mx = None
        for r in rows:
            v = r.get(field)
            if isinstance(v, str):
                if mx is None or v > mx:
                    mx = v
        return mx

    stats = {
        "scope": {"conversationId": conversationId},
        "counts": {
            "messages": {"total": msg_total, "stored": msg_stored, "redacted": msg_redacted},
            "active_files": {"total": af_total, "active": af_active, "inactive": af_inactive},
            "knowledge_items": {"total": ki_total, "by_type": ki_by_type, "by_status": ki_by_status},
            "episodes": {"total": ep_total, "recorded": ep_recorded, "voided": ep_voided}
        },
        "tokens": {
            "sum_token_count": token_sum,
            "messages_with_token_count": token_present
        },
        "freshness": {
            "messages_last_created_at": _max_ts(scoped_messages, "created_at"),
            "active_files_last_accessed_at": _max_ts(scoped_active_files, "last_accessed_at"),
            "knowledge_items_last_updated_at": _max_ts(scoped_knowledge, "updated_at"),
            "episodes_last_occurred_at": _max_ts(scoped_episodes, "occurred_at")
        }
    }

    # Validate non-negative aggregates
    def _nonneg(x):
        return isinstance(x, int) and x >= 0
    if not (_nonneg(msg_total) and _nonneg(af_total) and _nonneg(ki_total) and _nonneg(ep_total) and _nonneg(token_sum)):
        return _err("VALIDATION_ERROR", "invalid negative or null aggregates encountered")

    request_log.append({
        "id": f"c10x_req_{uuid.uuid4().hex}",
        "endpoint": endpoint,
        "conversation_id": conversationId,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "ts": ts
    })
    _save("request_log.json", request_log)

    return {"stats": stats}

def getConversation(conversation_id, include_context=None, recent_messages_limit=None, recent_episodes_limit=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_key(row, field):
        dt = _parse_dt(row.get(field))
        return dt if dt is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    def _ensure_request_log_loaded():
        # Optional: observable dynamics if a request log exists.
        candidates = ["request_logs.json", "requests.json", "audit_logs.json", "usage.json", "usage_logs.json"]
        for fn in candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                return fn, _load(fn)
        return None, None

    def _rate_limit_check_and_log(endpoint, status, latency_ms, meta=None):
        fn, logs = _ensure_request_log_loaded()
        if fn is None:
            return None  # No logging schema present; skip.
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        # Soft, generic rate-limit if logs exist: 120 req/min across the datastore.
        window_s = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp") or r.get("created_at") or r.get("at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= limit:
            # Still log the refused request if possible.
            row = {
                "id": f"c10x_req_{int(now.timestamp()*1000)}",
                "endpoint": endpoint,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "latency_ms": latency_ms,
                "timestamp": now.isoformat(),
                "meta": meta or {}
            }
            logs.append(row)
            _save(fn, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        row = {
            "id": f"c10x_req_{int(now.timestamp()*1000)}",
            "endpoint": endpoint,
            "status": status,
            "http_status": 200 if status == "OK" else 400,
            "latency_ms": latency_ms,
            "timestamp": now.isoformat(),
            "meta": meta or {}
        }
        logs.append(row)
        _save(fn, logs)
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(conversation_id, str) or not re.match(r"^c10x_convo_[A-Za-z0-9]+$", conversation_id or ""):
        latency_ms = int((time.time() - t0) * 1000)
        rl = _rate_limit_check_and_log("getConversation", "VALIDATION_ERROR", latency_ms, {"conversation_id": conversation_id})
        if rl: return rl
        return _err("VALIDATION_ERROR", "conversation_id is invalid.", field="conversation_id")

    if include_context is not None and not isinstance(include_context, bool):
        latency_ms = int((time.time() - t0) * 1000)
        rl = _rate_limit_check_and_log("getConversation", "VALIDATION_ERROR", latency_ms, {"conversation_id": conversation_id})
        if rl: return rl
        return _err("VALIDATION_ERROR", "include_context must be a boolean.", field="include_context")

    if recent_messages_limit is not None:
        if not isinstance(recent_messages_limit, int):
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("getConversation", "VALIDATION_ERROR", latency_ms, {"conversation_id": conversation_id})
            if rl: return rl
            return _err("VALIDATION_ERROR", "recent_messages_limit must be an integer.", field="recent_messages_limit")
        if recent_messages_limit < 1 or recent_messages_limit > 500:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("getConversation", "VALIDATION_ERROR", latency_ms, {"conversation_id": conversation_id})
            if rl: return rl
            return _err("VALIDATION_ERROR", "recent_messages_limit out of range (1..500).", field="recent_messages_limit")

    if recent_episodes_limit is not None:
        if not isinstance(recent_episodes_limit, int):
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("getConversation", "VALIDATION_ERROR", latency_ms, {"conversation_id": conversation_id})
            if rl: return rl
            return _err("VALIDATION_ERROR", "recent_episodes_limit must be an integer.", field="recent_episodes_limit")
        if recent_episodes_limit < 1 or recent_episodes_limit > 500:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("getConversation", "VALIDATION_ERROR", latency_ms, {"conversation_id": conversation_id})
            if rl: return rl
            return _err("VALIDATION_ERROR", "recent_episodes_limit out of range (1..500).", field="recent_episodes_limit")

    include_context = bool(include_context) if include_context is not None else False
    msg_lim = recent_messages_limit if recent_messages_limit is not None else 50
    ep_lim = recent_episodes_limit if recent_episodes_limit is not None else 50

    # Ambient auth: no explicit auth parameter; allow if data exists.
    conversations = _load("conversations.json")
    convo = None
    if isinstance(conversations, list):
        for c in conversations:
            if isinstance(c, dict) and c.get("id") == conversation_id:
                convo = c
                break
    if convo is None:
        latency_ms = int((time.time() - t0) * 1000)
        rl = _rate_limit_check_and_log("getConversation", "NOT_FOUND", latency_ms, {"conversation_id": conversation_id})
        if rl: return rl
        return _err("NOT_FOUND", "Conversation not found.", conversation_id=conversation_id)

    resp = {"conversation": convo}

    if include_context:
        messages = _load("messages.json")
        active_files = _load("active_files.json")
        knowledge_items = _load("knowledge_items.json")
        episodes = _load("episodes.json")

        # recent messages excluding redacted
        msg_rows = []
        if isinstance(messages, list):
            for m in messages:
                if isinstance(m, dict) and m.get("conversation_id") == conversation_id:
                    if m.get("status") == "redacted":
                        continue
                    msg_rows.append(m)
        msg_rows.sort(key=lambda r: (int(r.get("sequence") or 0), _dt_key(r, "created_at")), reverse=True)
        msg_rows = msg_rows[:msg_lim]

        # active files
        file_rows = []
        if isinstance(active_files, list):
            for af in active_files:
                if isinstance(af, dict) and af.get("conversation_id") == conversation_id and af.get("status") == "active":
                    file_rows.append(af)
        file_rows.sort(key=lambda r: _dt_key(r, "last_accessed_at"), reverse=True)

        # knowledge items: conversation scoped + global (conversation_id null)
        ki_rows = []
        if isinstance(knowledge_items, list):
            for ki in knowledge_items:
                if not isinstance(ki, dict):
                    continue
                if ki.get("status") != "active":
                    continue
                cid = ki.get("conversation_id")
                if cid is None or cid == conversation_id:
                    ki_rows.append(ki)
        ki_rows.sort(key=lambda r: _dt_key(r, "updated_at"), reverse=True)

        # recent episodes excluding voided
        ep_rows = []
        if isinstance(episodes, list):
            for e in episodes:
                if isinstance(e, dict) and e.get("conversation_id") == conversation_id:
                    if e.get("status") == "voided":
                        continue
                    ep_rows.append(e)
        ep_rows.sort(key=lambda r: (int(r.get("sequence") or 0), _dt_key(r, "occurred_at")), reverse=True)
        ep_rows = ep_rows[:ep_lim]

        resp["context"] = {
            "recent_messages": msg_rows,
            "active_files": file_rows,
            "active_knowledge_items": ki_rows,
            "recent_episodes": ep_rows
        }

    latency_ms = int((time.time() - t0) * 1000)
    rl = _rate_limit_check_and_log("getConversation", "OK", latency_ms, {"conversation_id": conversation_id, "include_context": include_context})
    if rl: return rl
    resp["meta"] = {"latency_ms": latency_ms}
    return resp

def listConversations(status=None, external_conversation_key=None, limit=None, cursor=None, started_after=None, started_before=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _dt_key(row, field):
        dt = _parse_dt(row.get(field))
        return dt if dt is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    def _ensure_request_log_loaded():
        candidates = ["request_logs.json", "requests.json", "audit_logs.json", "usage.json", "usage_logs.json"]
        for fn in candidates:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                return fn, _load(fn)
        return None, None

    def _rate_limit_check_and_log(endpoint, status_s, latency_ms, meta=None):
        fn, logs = _ensure_request_log_loaded()
        if fn is None:
            return None
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        limit_r = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs:
            ts = _parse_dt(r.get("timestamp") or r.get("created_at") or r.get("at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= limit_r:
            row = {
                "id": f"c10x_req_{int(now.timestamp()*1000)}",
                "endpoint": endpoint,
                "status": "RATE_LIMIT",
                "http_status": 429,
                "latency_ms": latency_ms,
                "timestamp": now.isoformat(),
                "meta": meta or {}
            }
            logs.append(row)
            _save(fn, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        row = {
            "id": f"c10x_req_{int(now.timestamp()*1000)}",
            "endpoint": endpoint,
            "status": status_s,
            "http_status": 200 if status_s == "OK" else 400,
            "latency_ms": latency_ms,
            "timestamp": now.isoformat(),
            "meta": meta or {}
        }
        logs.append(row)
        _save(fn, logs)
        return None

    t0 = time.time()

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "ended"):
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"status": status})
            if rl: return rl
            return _err("VALIDATION_ERROR", "status must be one of: active, ended.", field="status")

    if external_conversation_key is not None and not isinstance(external_conversation_key, str):
        latency_ms = int((time.time() - t0) * 1000)
        rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"external_conversation_key": external_conversation_key})
        if rl: return rl
        return _err("VALIDATION_ERROR", "external_conversation_key must be a string.", field="external_conversation_key")

    if limit is not None:
        if not isinstance(limit, int):
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"limit": limit})
            if rl: return rl
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 200:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"limit": limit})
            if rl: return rl
            return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")
    else:
        limit = 50

    sa = None
    sb = None
    if started_after is not None:
        if not isinstance(started_after, str) or _parse_dt(started_after) is None:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"started_after": started_after})
            if rl: return rl
            return _err("VALIDATION_ERROR", "started_after must be an RFC3339 datetime.", field="started_after")
        sa = _parse_dt(started_after)

    if started_before is not None:
        if not isinstance(started_before, str) or _parse_dt(started_before) is None:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"started_before": started_before})
            if rl: return rl
            return _err("VALIDATION_ERROR", "started_before must be an RFC3339 datetime.", field="started_before")
        sb = _parse_dt(started_before)

    if sa and sb and sa > sb:
        latency_ms = int((time.time() - t0) * 1000)
        rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"started_after": started_after, "started_before": started_before})
        if rl: return rl
        return _err("VALIDATION_ERROR", "started_after must be <= started_before.")

    # Cursor decode: base64 JSON with {"offset": int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"cursor": cursor})
            if rl: return rl
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                raise ValueError("bad cursor")
            offset = obj["offset"]
        except Exception:
            latency_ms = int((time.time() - t0) * 1000)
            rl = _rate_limit_check_and_log("listConversations", "VALIDATION_ERROR", latency_ms, {"cursor": cursor})
            if rl: return rl
            return _err("VALIDATION_ERROR", "cursor is invalid or expired.", field="cursor")

    # Ambient auth: allow list if datastore exists/readable.
    conversations = _load("conversations.json")
    if not isinstance(conversations, list):
        latency_ms = int((time.time() - t0) * 1000)
        rl = _rate_limit_check_and_log("listConversations", "UNAUTHORIZED", latency_ms, {})
        if rl: return rl
        return _err("UNAUTHORIZED", "Not permitted to list conversations.")

    rows = []
    for c in conversations:
        if not isinstance(c, dict):
            continue
        if status is not None and c.get("status") != status:
            continue
        if external_conversation_key is not None and c.get("external_conversation_key") != external_conversation_key:
            continue
        st = _parse_dt(c.get("started_at"))
        if sa and (st is None or st <= sa):
            continue
        if sb and (st is None or st >= sb):
            continue
        rows.append(c)

    rows.sort(key=lambda r: (_dt_key(r, "last_activity_at"), _dt_key(r, "started_at")), reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    rl = _rate_limit_check_and_log("listConversations", "OK", latency_ms, {"returned": len(page), "total": total})
    if rl: return rl

    return {
        "conversations": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "latency_ms": latency_ms
        }
    }

def redactMessage(message_id, reason=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0397000" if __import__("os").path.isdir("./environment_mix/0397000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "redactMessage"

    def _utc_now_iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(ts):
        if isinstance(ts, str) and ts.endswith("Z"):
            try:
                return datetime.datetime.fromisoformat(ts[:-1] + "+00:00")
            except Exception:
                return None
        return None

    def _log_request(status_code, meta=None):
        now = _utc_now_iso_z()
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "c10x_req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_id": None,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": now,
                "meta": meta or {},
            }
        )
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        rate_limits = _load("rate_limits.json")
        if not isinstance(rate_limits, list):
            return None
        rl = next((r for r in rate_limits if r.get("enabled") is True and r.get("endpoint") == endpoint), None)
        if rl is None:
            rl = next((r for r in rate_limits if r.get("enabled") is True and r.get("endpoint") == "*"), None)
        if not rl:
            return None
        try:
            window_s = int(rl.get("window_seconds"))
            max_req = int(rl.get("max_requests"))
        except Exception:
            return None
        if window_s <= 0 or max_req < 0:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = time.time() - window_s
        cnt = 0
        for r in logs:
            if r.get("endpoint") != endpoint:
                continue
            dt = _parse_ts(r.get("timestamp"))
            if dt is None:
                continue
            if dt.timestamp() >= cutoff:
                cnt += 1
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded.", endpoint=endpoint, window_seconds=window_s, max_requests=max_req)
        return None

    rl_err = _enforce_rate_limit()
    if rl_err:
        _log_request("RATE_LIMIT", {"message_id": message_id})
        return rl_err

    if not isinstance(message_id, str) or not re.match(r"^c10x_msg_[A-Za-z0-9]+$", message_id):
        _log_request("VALIDATION_ERROR", {"field": "message_id"})
        return _err("VALIDATION_ERROR", "Invalid message_id format.", field="message_id")

    if reason is not None and not isinstance(reason, str):
        _log_request("VALIDATION_ERROR", {"field": "reason"})
        return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    msg = next((m for m in messages if m.get("id") == message_id), None)
    if msg is None:
        _log_request("NOT_FOUND", {"message_id": message_id})
        return _err("NOT_FOUND", "Message not found.", message_id=message_id)

    if msg.get("status") == "redacted":
        _log_request("CONFLICT", {"message_id": message_id})
        return _err("CONFLICT", "Message is already redacted.", message_id=message_id)

    # Enforce lifecycle transition stored -> redacted
    if msg.get("status") != "stored":
        _log_request("INVALID_TRANSITION", {"message_id": message_id, "from_status": msg.get("status"), "to_status": "redacted"})
        return _err("INVALID_TRANSITION", "Illegal message status transition.", message_id=message_id)

    now = _utc_now_iso_z()
    msg["status"] = "redacted"
    msg["redacted_at"] = now
    msg["updated_at"] = now
    _save("messages.json", messages)

    # Also update owning conversation last_activity_at, since this is a write within conversation scope
    conv_id = msg.get("conversation_id")
    if isinstance(conv_id, str) and conv_id:
        conversations = _load("conversations.json")
        if not isinstance(conversations, list):
            conversations = []
        convo = next((c for c in conversations if c.get("id") == conv_id), None)
        if convo is not None:
            convo["last_activity_at"] = now
            convo["updated_at"] = now
            _save("conversations.json", conversations)

    # If audit log collection exists, store reason there; otherwise include in request meta only
    meta = {"message_id": message_id}
    if reason:
        meta["reason"] = reason
    _log_request("OK", meta)
    return {"message": msg}
